package com.lab.management;

import com.formdev.flatlaf.FlatLightLaf;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;

public class ManagementApp extends JFrame {
    private static final String URL = "jdbc:h2:file:./data/labdb";
    private static final Color BG = new Color(245,247,251), NAVY = new Color(23,37,84);
    private static final Color BLUE = new Color(37,99,235), GREEN = new Color(5,150,105), RED = new Color(220,38,38);
    private final DefaultTableModel em = model("ID","Name","Email","Department");
    private final DefaultTableModel qm = model("ID","Name","Category","Status","Assigned Employee");
    private JTable et, qt;
    private JTextField en, ee, ed, qn, qc;
    private JComboBox<Person> assigned;
    private JLabel ec, qcLabel, ac;

    public ManagementApp() {
        super("Employee & Equipment Management");
        if (!initDb()) { dispose(); return; }
        setDefaultCloseOperation(EXIT_ON_CLOSE); setSize(1200,760); setMinimumSize(new Dimension(1000,650)); setLocationRelativeTo(null);
        setContentPane(ui()); refresh();
    }
    private static DefaultTableModel model(String... c) { return new DefaultTableModel(c,0) { public boolean isCellEditable(int r,int c){return false;} }; }
    private Connection db() throws SQLException { return DriverManager.getConnection(URL,"sa",""); }
    private boolean initDb() {
        try {
            Class.forName("org.h2.Driver");
            try(Connection c=db(); Statement s=c.createStatement()) {
                s.execute("CREATE TABLE IF NOT EXISTS employees(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,department VARCHAR(120) NOT NULL)");
                s.execute("CREATE TABLE IF NOT EXISTS equipment(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,category VARCHAR(120) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'Available',employee_id BIGINT,CONSTRAINT fk_employee FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE SET NULL)");
            } return true;
        } catch(Exception x) { JOptionPane.showMessageDialog(null,"Database startup error:\n"+x.getMessage()); return false; }
    }
    private JPanel ui() {
        JPanel root=new JPanel(new BorderLayout(0,18)); root.setBackground(BG); root.setBorder(new EmptyBorder(22,24,20,24));
        JPanel header=new JPanel(new BorderLayout()); header.setOpaque(false);
        JPanel titles=new JPanel(); titles.setOpaque(false); titles.setLayout(new BoxLayout(titles,BoxLayout.Y_AXIS));
        JLabel title=new JLabel("Employee & Equipment Management"); title.setFont(new Font("Segoe UI",Font.BOLD,27)); title.setForeground(NAVY);
        JLabel sub=new JLabel("Manage your people, inventory and assignments in one place"); sub.setForeground(new Color(100,116,139));
        titles.add(title); titles.add(Box.createVerticalStrut(5)); titles.add(sub); header.add(titles,BorderLayout.WEST);
        JLabel tag=new JLabel("  ● LOCAL DATABASE  "); tag.setOpaque(true); tag.setBackground(new Color(220,252,231)); tag.setForeground(new Color(22,101,52)); tag.setBorder(new EmptyBorder(9,8,9,8)); header.add(tag,BorderLayout.EAST);
        JPanel stats=new JPanel(new GridLayout(1,3,15,0)); stats.setOpaque(false);
        ec=stat(stats,"TOTAL EMPLOYEES",BLUE); qcLabel=stat(stats,"TOTAL EQUIPMENT",new Color(124,58,237)); ac=stat(stats,"ASSIGNED EQUIPMENT",GREEN);
        JPanel top=new JPanel(new BorderLayout(0,18)); top.setOpaque(false); top.add(header,BorderLayout.NORTH); top.add(stats,BorderLayout.SOUTH); root.add(top,BorderLayout.NORTH);
        JTabbedPane tabs=new JTabbedPane(); tabs.setFont(new Font("Segoe UI",Font.BOLD,14)); tabs.addTab("  Employees  ",employeePanel()); tabs.addTab("  Equipment  ",equipmentPanel()); root.add(tabs,BorderLayout.CENTER);
        JLabel foot=new JLabel("Java Swing  •  FlatLaf  •  JDBC  •  H2 Database"); foot.setForeground(new Color(148,163,184)); foot.setFont(new Font("Segoe UI",Font.PLAIN,11)); root.add(foot,BorderLayout.SOUTH);
        return root;
    }
    private JLabel stat(JPanel parent,String heading,Color accent) {
        JPanel card=new JPanel(new BorderLayout(0,10)); card.setBackground(Color.WHITE);
        card.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0,4,0,0,accent),BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(226,232,240)),new EmptyBorder(15,18,15,18))));
        JLabel h=new JLabel(heading); h.setFont(new Font("Segoe UI",Font.BOLD,11)); h.setForeground(new Color(100,116,139));
        JLabel v=new JLabel("0"); v.setFont(new Font("Segoe UI",Font.BOLD,30)); v.setForeground(NAVY); card.add(h,BorderLayout.NORTH); card.add(v,BorderLayout.CENTER); parent.add(card); return v;
    }
    private JPanel employeePanel() {
        JPanel p=new JPanel(new BorderLayout(15,0)); p.setBackground(BG); p.setBorder(new EmptyBorder(15,2,3,2));
        et=new JTable(em); style(et); p.add(scroll(et),BorderLayout.CENTER);
        JPanel side=sidePanel(); JPanel form=form("EMPLOYEE DETAILS");
        en=field(form,"Full name"); ee=field(form,"Email address"); ed=field(form,"Department"); side.add(form); gap(side,12);
        addBtn(side,"＋  Add employee",BLUE,this::addEmployee); addBtn(side,"Update selected",NAVY,this::updateEmployee); addBtn(side,"Delete selected",RED,this::deleteEmployee); addBtn(side,"Clear form",new Color(71,85,105),this::clearEmployee); addBtn(side,"Refresh data",new Color(71,85,105),this::refresh);
        et.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&et.getSelectedRow()>=0){int r=et.convertRowIndexToModel(et.getSelectedRow());en.setText(v(em,r,1));ee.setText(v(em,r,2));ed.setText(v(em,r,3));}});
        p.add(side,BorderLayout.EAST); return p;
    }
    private JPanel equipmentPanel() {
        JPanel p=new JPanel(new BorderLayout(15,0)); p.setBackground(BG); p.setBorder(new EmptyBorder(15,2,3,2));
        qt=new JTable(qm); style(qt); p.add(scroll(qt),BorderLayout.CENTER);
        JPanel side=sidePanel(); JPanel form=form("EQUIPMENT DETAILS");
        qn=field(form,"Equipment name"); qc=field(form,"Category");
        JLabel l=new JLabel("Assign to employee"); l.setFont(new Font("Segoe UI",Font.BOLD,12)); l.setBorder(new EmptyBorder(8,0,5,0)); form.add(l);
        assigned=new JComboBox<>(); assigned.setMaximumSize(new Dimension(Integer.MAX_VALUE,38)); assigned.setAlignmentX(Component.LEFT_ALIGNMENT); form.add(assigned);
        side.add(form); gap(side,12);
        addBtn(side,"＋  Add equipment",BLUE,this::addEquipment); addBtn(side,"Update selected",NAVY,this::updateEquipment); addBtn(side,"Delete selected",RED,this::deleteEquipment); addBtn(side,"Assign / unassign",GREEN,this::saveAssignment); addBtn(side,"Clear form",new Color(71,85,105),this::clearEquipment); addBtn(side,"Refresh data",new Color(71,85,105),this::refresh);
        qt.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&qt.getSelectedRow()>=0){int r=qt.convertRowIndexToModel(qt.getSelectedRow());qn.setText(v(qm,r,1));qc.setText(v(qm,r,2));loadAssignment(Long.parseLong(v(qm,r,0)));}});
        p.add(side,BorderLayout.EAST); return p;
    }
    private JPanel sidePanel(){ JPanel p=new JPanel();p.setOpaque(false);p.setPreferredSize(new Dimension(285,0));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));return p; }
    private JPanel form(String heading){JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(226,232,240)),new EmptyBorder(14,15,15,15)));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel h=new JLabel(heading);h.setFont(new Font("Segoe UI",Font.BOLD,11));h.setForeground(new Color(100,116,139));h.setBorder(new EmptyBorder(0,0,8,0));h.setAlignmentX(Component.LEFT_ALIGNMENT);p.add(h);p.setAlignmentX(Component.LEFT_ALIGNMENT);return p;}
    private JTextField field(JPanel p,String label){JLabel l=new JLabel(label);l.setFont(new Font("Segoe UI",Font.BOLD,12));l.setBorder(new EmptyBorder(8,0,5,0));l.setAlignmentX(Component.LEFT_ALIGNMENT);p.add(l);JTextField f=new JTextField();f.setMaximumSize(new Dimension(Integer.MAX_VALUE,36));f.setAlignmentX(Component.LEFT_ALIGNMENT);p.add(f);return f;}
    private void addBtn(JPanel p,String text,Color color,Runnable action){JButton b=new JButton(text);b.setFont(new Font("Segoe UI",Font.BOLD,13));b.setForeground(Color.WHITE);b.setBackground(color);b.setOpaque(true);b.setBorderPainted(false);b.setFocusPainted(false);b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setMaximumSize(new Dimension(Integer.MAX_VALUE,41));b.setPreferredSize(new Dimension(275,41));b.addActionListener(e->action.run());gap(p,7);p.add(b);}
    private void gap(JPanel p,int n){p.add(Box.createVerticalStrut(n));}
    private JScrollPane scroll(JTable t){JScrollPane s=new JScrollPane(t);s.setBorder(BorderFactory.createLineBorder(new Color(226,232,240)));s.getViewport().setBackground(Color.WHITE);return s;}
    private void style(JTable t){t.setRowHeight(34);t.setFont(new Font("Segoe UI",Font.PLAIN,13));t.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);t.setFillsViewportHeight(true);t.setShowVerticalLines(false);t.setGridColor(new Color(226,232,240));t.setSelectionBackground(new Color(219,234,254));t.getTableHeader().setFont(new Font("Segoe UI",Font.BOLD,12));t.getTableHeader().setBackground(new Color(239,244,250));t.getTableHeader().setForeground(NAVY);t.getTableHeader().setPreferredSize(new Dimension(0,38));t.getTableHeader().setReorderingAllowed(false);}
    private String v(DefaultTableModel m,int r,int c){Object o=m.getValueAt(r,c);return o==null?"":o.toString();}
    private void addEmployee(){String n=en.getText().trim(),e=ee.getText().trim(),d=ed.getText().trim();if(n.isEmpty()||e.isEmpty()||d.isEmpty()){msg("Enter name, email and department.",false);return;}if(!e.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")){msg("Enter a valid email address.",false);return;}try(Connection c=db();PreparedStatement s=c.prepareStatement("INSERT INTO employees(name,email,department) VALUES(?,?,?)")){s.setString(1,n);s.setString(2,e);s.setString(3,d);s.executeUpdate();clearEmployee();refresh();msg("Employee added successfully.",true);}catch(SQLException x){msg("Could not add employee: "+sqlMessage(x),false);}}
    private void updateEmployee(){Long id=selected(et,em);if(id==null){msg("Select an employee first.",false);return;}String n=en.getText().trim(),e=ee.getText().trim(),d=ed.getText().trim();if(n.isEmpty()||e.isEmpty()||d.isEmpty()||!e.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")){msg("Enter a name, valid email and department.",false);return;}try(Connection c=db();PreparedStatement s=c.prepareStatement("UPDATE employees SET name=?,email=?,department=? WHERE id=?")){s.setString(1,n);s.setString(2,e);s.setString(3,d);s.setLong(4,id);s.executeUpdate();refresh();msg("Employee updated.",true);}catch(SQLException x){msg("Could not update: "+sqlMessage(x),false);}}
    private void deleteEmployee(){Long id=selected(et,em);if(id==null){msg("Select an employee first.",false);return;}if(JOptionPane.showConfirmDialog(this,"Delete this employee? Assigned equipment becomes unassigned.","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(Connection c=db();PreparedStatement s=c.prepareStatement("DELETE FROM employees WHERE id=?")){s.setLong(1,id);s.executeUpdate();clearEmployee();refresh();msg("Employee deleted.",true);}catch(SQLException x){msg("Could not delete: "+sqlMessage(x),false);}}
    private void addEquipment(){String n=qn.getText().trim(),cat=qc.getText().trim();if(n.isEmpty()||cat.isEmpty()){msg("Enter equipment name and category.",false);return;}try(Connection c=db();PreparedStatement s=c.prepareStatement("INSERT INTO equipment(name,category,status,employee_id) VALUES(?,?,'Available',NULL)")){s.setString(1,n);s.setString(2,cat);s.executeUpdate();clearEquipment();refresh();msg("Equipment added successfully.",true);}catch(SQLException x){msg("Could not add equipment: "+x.getMessage(),false);}}
    private void updateEquipment(){Long id=selected(qt,qm);if(id==null){msg("Select equipment first.",false);return;}String n=qn.getText().trim(),cat=qc.getText().trim();if(n.isEmpty()||cat.isEmpty()){msg("Enter equipment name and category.",false);return;}try(Connection c=db();PreparedStatement s=c.prepareStatement("UPDATE equipment SET name=?,category=? WHERE id=?")){s.setString(1,n);s.setString(2,cat);s.setLong(3,id);s.executeUpdate();refresh();msg("Equipment updated.",true);}catch(SQLException x){msg("Could not update: "+x.getMessage(),false);}}
    private void deleteEquipment(){Long id=selected(qt,qm);if(id==null){msg("Select equipment first.",false);return;}if(JOptionPane.showConfirmDialog(this,"Delete this equipment item?","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(Connection c=db();PreparedStatement s=c.prepareStatement("DELETE FROM equipment WHERE id=?")){s.setLong(1,id);s.executeUpdate();clearEquipment();refresh();msg("Equipment deleted.",true);}catch(SQLException x){msg("Could not delete: "+x.getMessage(),false);}}
    private void saveAssignment(){Long id=selected(qt,qm);if(id==null){msg("Select equipment first.",false);return;}Person person=(Person)assigned.getSelectedItem();Long emp=person==null?null:person.id;String sql=emp==null?"UPDATE equipment SET employee_id=NULL,status='Available' WHERE id=?":"UPDATE equipment SET employee_id=?,status='Assigned' WHERE id=?";try(Connection c=db();PreparedStatement s=c.prepareStatement(sql)){if(emp==null)s.setLong(1,id);else{s.setLong(1,emp);s.setLong(2,id);}s.executeUpdate();refresh();msg(emp==null?"Equipment unassigned.":"Equipment assigned successfully.",true);}catch(SQLException x){msg("Could not assign: "+x.getMessage(),false);}}
    private void loadAssignment(long id){try(Connection c=db();PreparedStatement s=c.prepareStatement("SELECT employee_id FROM equipment WHERE id=?")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(r.next()){long assignedId=r.getLong(1);boolean wasNull=r.wasNull();for(int i=0;i<assigned.getItemCount();i++){Person p=assigned.getItemAt(i);if((wasNull&&p.id==null)||(!wasNull&&p.id!=null&&p.id==assignedId)){assigned.setSelectedIndex(i);break;}}}}}catch(SQLException x){msg(x.getMessage(),false);}}
    private Long selected(JTable t,DefaultTableModel m){if(t==null||t.getSelectedRow()<0)return null;try{return Long.parseLong(v(m,t.convertRowIndexToModel(t.getSelectedRow()),0));}catch(Exception x){return null;}}
    private void refresh(){if(et==null)return;em.setRowCount(0);try(Connection c=db();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,name,email,department FROM employees ORDER BY id")){while(r.next())em.addRow(new Object[]{r.getLong(1),r.getString(2),r.getString(3),r.getString(4)});}catch(SQLException x){msg(x.getMessage(),false);}
        if(assigned!=null){Object old=assigned.getSelectedItem();assigned.removeAllItems();assigned.addItem(new Person(null,"— Unassigned —"));try(Connection c=db();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,name FROM employees ORDER BY name")){while(r.next())assigned.addItem(new Person(r.getLong(1),r.getString(2)+" (ID "+r.getLong(1)+")"));}catch(SQLException x){msg(x.getMessage(),false);}if(old instanceof Person oldP)for(int i=0;i<assigned.getItemCount();i++)if(java.util.Objects.equals(assigned.getItemAt(i).id,oldP.id)){assigned.setSelectedIndex(i);break;}}
        qm.setRowCount(0);try(Connection c=db();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT q.id,q.name,q.category,q.status,e.name FROM equipment q LEFT JOIN employees e ON q.employee_id=e.id ORDER BY q.id")){while(r.next())qm.addRow(new Object[]{r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)==null?"—":r.getString(5)});}catch(SQLException x){msg(x.getMessage(),false);}
        try(Connection c=db();Statement s=c.createStatement()){try(ResultSet r=s.executeQuery("SELECT COUNT(*) FROM employees")){if(r.next())ec.setText(r.getString(1));}try(ResultSet r=s.executeQuery("SELECT COUNT(*) FROM equipment")){if(r.next())qcLabel.setText(r.getString(1));}try(ResultSet r=s.executeQuery("SELECT COUNT(*) FROM equipment WHERE employee_id IS NOT NULL")){if(r.next())ac.setText(r.getString(1));}}catch(SQLException x){msg(x.getMessage(),false);}
    }
    private void clearEmployee(){en.setText("");ee.setText("");ed.setText("");if(et!=null)et.clearSelection();}
    private void clearEquipment(){qn.setText("");qc.setText("");if(assigned!=null&&assigned.getItemCount()>0)assigned.setSelectedIndex(0);if(qt!=null)qt.clearSelection();}
    private String sqlMessage(SQLException x){return x.getErrorCode()==23505?"That email already exists.":x.getMessage();}
    private void msg(String s,boolean ok){JOptionPane.showMessageDialog(this,s,"Employee & Equipment Management",ok?JOptionPane.INFORMATION_MESSAGE:JOptionPane.WARNING_MESSAGE);}
    private static class Person{final Long id;final String label;Person(Long id,String label){this.id=id;this.label=label;}public String toString(){return label;}}
    public static void main(String[] args){try{FlatLightLaf.setup();UIManager.put("Component.arc",10);UIManager.put("Button.arc",10);UIManager.put("TextComponent.arc",8);}catch(Exception e){System.err.println(e.getMessage());}SwingUtilities.invokeLater(()->new ManagementApp().setVisible(true));}
}
